export default async function f(
  { body, templateId, sheetFolder, presentationFolder, acknowledge, resolution, confirmedId },
  ctx,
) {
  const { fileId, leads } = body || {};
  const fields = [
    "First Name",
    "Last Name",
    "Full Name",
    "Title",
    "Email",
    "Company",
    "Contact Location",
    "Employees",
    "Phone",
    "Industry",
    "Country",
    "State",
    "City",
    "Keywords",
  ];
  if (
    !fileId ||
    !Array.isArray(leads) ||
    !leads.length ||
    !templateId ||
    !sheetFolder ||
    !presentationFolder
  )
    throw Error("Configure source file, leads and destination IDs");
  for (const row of leads)
    if (!row["First Name"] || !row["Full Name"] || !row.Company || !row.Email)
      throw Error("Each lead requires First Name, Full Name, Company and Email");
  const key = "leads:" + fileId;
  const input = JSON.stringify({ fileId, leads, templateId, sheetFolder, presentationFolder });
  let s = await ctx.state.get(key);
  if (!s) {
    s = { input, status: "ready-create", index: 0 };
    await ctx.state.set(key, s);
  }
  if (s.input !== input) throw Error("Input changed for source file");
  if (s.status.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect unknown write " + key + " " + s.status);
    let p = s.status.slice(8);
    if (resolution === "absent") s.status = "ready-" + p;
    else if (p === "create") {
      if (!confirmedId) throw Error("Confirmed spreadsheet ID required");
      s.sheetId = confirmedId;
      s.status = "ready-fill";
    } else if (p === "fill") s.status = "ready-copy";
    else if (p === "copy") {
      if (!confirmedId) throw Error("Confirmed presentation ID required");
      s.presentationId = confirmedId;
      s.status = "ready-replace";
    } else if (p === "replace") s.status = "ready-update";
    else if (p === "update") {
      s.index++;
      s.presentationId = "";
      s.status = s.index === leads.length ? "done" : "ready-copy";
    }
    await ctx.state.set(key, s);
  }
  const phase = s.status.replace("ready-", ""),
    lead = leads[s.index] || leads[0];
  if (phase !== "done") {
    s.status = "pending-" + phase;
    await ctx.state.set(key, s);
  }
  return {
    phase,
    key,
    sheetId: s.sheetId || "uncreated",
    presentationId: s.presentationId || templateId,
    templateId,
    sheetName: "Leads_" + fileId,
    copyName: lead.Company + " X MYCOMPANYNAME",
    sheetParents: [sheetFolder],
    presentationParents: [presentationFolder],
    range: "A1:O" + (leads.length + 1),
    values: [
      fields.concat("PresentationID"),
      ...leads.map((r) => fields.map((k) => String(r[k] ?? "")).concat("")),
    ],
    updateRange: "O" + (s.index + 2),
    updateValues: [[s.presentationId || ""]],
    requests: [
      ["{COMPANYNAME}", lead.Company],
      ["{Testdurchgestrichen}", lead["Full Name"]],
      ["{nichtdurchgestrichen}", lead["First Name"]],
    ].map(([text, replaceText]) => ({
      replaceAllText: { containsText: { text, matchCase: false }, replaceText },
    })),
  };
}

