async function f({ key, phase, actualId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.status !== "pending-" + phase) throw Error("Unexpected state");
  const { leads } = JSON.parse(s.input);
  if (phase === "create") {
    if (!actualId) throw Error("Unknown spreadsheet result");
    s.sheetId = actualId;
    s.status = "ready-fill";
  } else if (phase === "fill") {
    if (actualId !== s.sheetId) throw Error("Wrong spreadsheet");
    s.status = "ready-copy";
  } else if (phase === "copy") {
    if (!actualId) throw Error("Unknown copy result");
    s.presentationId = actualId;
    s.status = "ready-replace";
  } else if (phase === "replace") {
    if (actualId !== s.presentationId) throw Error("Wrong presentation");
    s.status = "ready-update";
  } else if (phase === "update") {
    if (actualId !== s.sheetId) throw Error("Wrong spreadsheet");
    s.index++;
    s.presentationId = "";
    s.status = s.index === leads.length ? "done" : "ready-copy";
  } else throw Error("Invalid phase");
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return f({ ...input, phase: "create" }, ctx);
}

